code_sketch:
def tail(path):                      # one line per pull, constant memory
    with open(path) as f:            # closed when the generator closes
        for line in f:
            yield line.rstrip("\n")

for i, line in enumerate(tail("app.log")):
    if "ERROR" in line:
        print(i, line)               # early exit stops reading the file

